next_code:
program nilai_mutlak
kamus
    x, mask, hasil : integer
algoritma
    input(x)

    // 1. Membuat bitmask (topeng bit)
    // Geser bit paling kiri (sign bit) ke kanan sebanyak 31 kali.
    // Jika x positif, mask = 0. Jika x negatif, mask = -1.
    mask <- x >> 31

    // 2. Menghitung nilai mutlak dengan rumus bitwise
    // Rumus: (x XOR mask) - mask
    hasil <- (x xor mask) - mask

    output(hasil)
endprogram

