Program CekDigitMenaik
{
    Kamus:
        N : integer
        d1, d2, d3, d4 : integer
        hasil : boolean

    Algoritma:
        // Membaca masukan sebagai satu bilangan bulat[span_1](start_span)[span_1](end_span)
        read(N)[span_2](start_span)[span_2](end_span)

        // Ekstraksi digit dari bilangan empat digit[span_3](start_span)[span_3](end_span)
        d1 <- N div 1000
        d2 <- (N mod 1000) div 100
        d3 <- (N mod 100) div 10
        d4 <- N mod 10

        // Menentukan apakah digit tersusun menaik secara Boolean tanpa percabangan[span_4](start_span)[span_4](end_span)
        hasil <- ((d1 < d2) and (d2 < d3)) and (d3 < d4)[span_5](start_span)[span_5](end_span)

        // Menampilkan keluaran nilai Boolean[span_6](start_span)[span_6](end_span)
        write(hasil)[span_7](start_span)[span_7](end_span)
}

