Program CekDigitMenaik
{
    Kamus:
        x : integer
        A, B, C, D : integer
        hasil : boolean

    Algoritma:
        // Membaca masukan sebagai satu bilangan bulat
        read(x)

        // Ekstraksi digit menggunakan rumusmu
        A <- x div 1000
        B <- x div 100 mod 10
        C <- x div 10 mod 10
        D <- x mod 10

        // Menentukan apakah digit tersusun menaik secara Boolean
        hasil <- ((A < B) and (B < C)) and (C < D)

        // Menampilkan keluaran nilai Boolean (true/false)
        write(hasil)
}

